window.HELO_FABRICS=[{"id": "cotton-linen", "name": "Cotton Linen", "cn": "棉麻", "traits": ["Natural blend", "Breathable", "Relaxed texture", "Everyday style"], "description": "Cotton-linen is a natural blend of cotton and linen, combining cotton softness with linen breathability and crispness. Its natural texture and relaxed style suit summer wear and home textiles.", "feel": "A softly textured surface with visible woven fibres. Wrinkling is natural to the fabric and part of its relaxed character.", "wear": "A starting point for summer layers, relaxed workwear and everyday clothing.", "care": "Follow the garment care label. When machine washing is allowed, use cool or warm water, wash similar colours together and avoid high heat.", "notice": "The exact feel and care depend on the blend and finish. Check the fibre label for the actual composition.", "image": "assets/library/detail-01.webp", "occasion": "vacation", "page": 0}, {"id": "wool", "name": "Wool", "cn": "⽺⽑", "traits": ["Natural animal fibre", "Warm", "Stretchy"], "description": "Wool comes from sheep. Its fibres trap air, which helps keep you warm. It is often used to make sweaters, coats, scarves and socks. Different types of wool feel different. Fine wool is usually softer, while some wool may feel a little itchy.", "feel": "Wool often feels springy when you press it, and its surface may look a little fluffy. But the feel and look can change depending on how the fabric is made and whether it is blended with other fibres. It can be hard to identify wool by touch alone.", "wear": "Wool is a good choice for cooler days in autumn and winter. You can wear a wool sweater on its own or as a warm layer. Wool coats and scarves are useful in cold weather.", "care": "Heat, strong rubbing and tumble drying can make wool shrink or lose its shape. Check the care label first. If it can be washed at home, use cool water and a wool detergent, then lay it flat to dry.", "notice": "", "image": "assets/library/detail-05.webp", "occasion": "winter", "page": 2}, {"id": "cotton", "name": "Cotton", "cn": "棉布", "traits": ["Natural plant fibre", "Soft", "Breathable", "Absorbent"], "description": "Cotton comes from the soft fibres around the seeds of the cotton plant. It is comfortable, breathable and able to absorb moisture. Cotton is widely used for T-shirts, shirts, underwear, jeans, towels and bedding. Its thickness and texture can vary depending on how it is woven or knitted.", "feel": "Cotton usually feels soft, dry and comfortable against the skin. Some cotton fabrics are smooth and light, while others are thick and firm. Cotton often creases easily, but this can help you distinguish it from some synthetic fabrics.", "wear": "Cotton is suitable for everyday clothing and warmer weather. Lightweight cotton is a good choice for summer because it allows air to move through the fabric. Thicker cotton, such as denim or cotton canvas, can be used for trousers, jackets and bags.", "care": "Always check the care label first. Most cotton clothes can be machine washed, but hot water and high-temperature drying may cause shrinking or fading. Wash similar colours together and use a lower temperature when you are unsure.", "notice": "Cotton is breathable, absorbent and usually gentle on the skin. However, it can wrinkle easily, take longer to dry and sometimes shrink after washing. Dark cotton fabrics may also lose colour over time.", "image": "assets/library/detail-02.webp", "occasion": "everyday", "page": 3}, {"id": "linen", "name": "Linen", "cn": "亚麻", "traits": ["Natural plant fibre", "Breathable", "Lightweight", "Quick-drying"], "description": "Linen is made from the fibres of the flax plant. It is breathable, absorbent and dries relatively quickly, making it a popular fabric for warm weather. Linen is often used for shirts, dresses, trousers, tablecloths, curtains and bedding.", "feel": "Linen usually feels cool, dry and slightly firm. Its surface may have visible lines, small knots or natural variations. New linen can feel a little stiff, but it often becomes softer after repeated washing and use.", "wear": "Linen is especially suitable for spring and summer. Loose linen shirts, dresses and trousers allow air to circulate and can feel comfortable in hot weather. Linen jackets and suits also work well for casual or smart-casual occasions.", "care": "Check the care label before washing. Many linen items can be machine washed on a gentle cycle with cool or warm water. Avoid high-temperature drying because it may cause shrinking and heavy creasing. Reshape the item while damp, then air-dry it. Iron while slightly damp if you want a smoother finish.", "notice": "Linen is breathable, durable and becomes softer with use. However, it wrinkles very easily, and some linen fabrics may feel rough at first. Light-coloured linen can also be slightly transparent, so you may need to consider suitable underwear or an inner layer.", "image": "assets/library/swatch-06.webp", "occasion": "vacation", "page": 4}, {"id": "cashmere", "name": "Cashmere", "cn": "⽺绒", "traits": ["Natural animal fibre", "Very soft", "Lightweight", "Warm"], "description": "Cashmere is a fine natural fibre collected from the soft undercoat of cashmere goats. It feels lighter and softer than ordinary wool while still providing excellent warmth. It is often used for sweaters, scarves, cardigans and winter accessories.", "feel": "Cashmere usually feels very soft, smooth and slightly fluffy. High-quality cashmere should feel warm without being heavy or rough. Its surface may develop small balls of fibre, known as pilling, especially in areas that experience frequent rubbing.", "wear": "Cashmere is ideal for autumn and winter. A lightweight cashmere sweater can be worn indoors, while thicker pieces provide warmth in colder weather. Its soft and refined appearance also makes it suitable for work, formal occasions and everyday outfits.", "care": "Wash cashmere gently by hand in cool water with a mild wool detergent, unless the care label recommends dry cleaning. Do not rub, twist or wring the fabric. Press out excess water with a towel, reshape the item and lay it flat to dry. Fold cashmere for storage instead of hanging it, as hangers may stretch the shoulders.", "notice": "Cashmere is warm, breathable and extremely soft against the skin. It is also lightweight, so it can provide warmth without feeling bulky. However, cashmere is delicate, often more expensive than ordinary wool and may lose its shape if handled carelessly.", "image": "assets/library/white-08.webp", "occasion": "work", "page": 5}, {"id": "silk", "name": "Silk", "cn": "真丝", "traits": ["Natural animal fibre", "Smooth", "Lightweight", "Breathable"], "description": "Silk is a natural fibre produced by silkworms. It is known for its smooth surface, soft drape and gentle shine. Silk is often used for shirts, dresses, scarves, pyjamas, ties and luxury bedding.", "feel": "Silk usually feels smooth, soft and cool against the skin. It has a natural shine that changes slightly under different lighting. The fabric drapes easily and moves gracefully, but some types of silk may have a more textured or matte surface.", "wear": "Silk is suitable for both everyday and formal clothing. Silk shirts and scarves can be worn to work, while dresses, ties and other elegant pieces are suitable for dinners, celebrations and special occasions. Lightweight silk can feel cool in warm weather and provide gentle insulation when layered.", "care": "Always follow the care label. Some silk items require dry cleaning, while others can be gently hand-washed in cool water with a silk detergent. Do not rub, twist or soak the fabric for a long time. Keep it away from direct sunlight and lay it flat or hang it carefully to air-dry. Iron on a low-temperature setting from the reverse side.", "notice": "Silk is lightweight, breathable and comfortable against the skin. Its smooth texture and natural shine create a refined appearance. However, silk is delicate and may be damaged by sweat, perfume, strong sunlight or rough surfaces. Water can also leave marks on some silk fabrics.", "image": "assets/library/detail-03.webp", "occasion": "occasion", "page": 6}, {"id": "hemp", "name": "Hemp", "cn": "麻布", "traits": ["Natural plant fibre", "Strong", "Breathable", "Durable"], "description": "Hemp fabric is made from the fibres of the hemp plant. It is one of the strongest natural fabrics and is often used for shirts, trousers, jackets, bags and home textiles. New hemp fabric may feel firm, but it usually becomes softer with washing and regular use.", "feel": "Hemp often feels dry, textured and slightly firm. Its surface may show natural lines and small irregularities, giving it a relaxed and organic appearance. It can look similar to linen, but hemp is often heavier and feels more durable.", "wear": "Lightweight hemp clothing is suitable for spring and summer because the fabric is breathable and absorbs moisture. Thicker hemp can be used for trousers, jackets, workwear and bags. Its natural texture works especially well for casual and outdoor styles.", "care": "Check the care label before washing. Most hemp fabrics can be machine-washed in cool or warm water using a gentle cycle. Avoid strong bleach and high-temperature drying, as these may weaken the fibres or cause shrinking. Reshape the item while damp and allow it to air-dry. Iron it while slightly damp if you prefer a smoother finish.", "notice": "Hemp is strong, breathable and resistant to everyday wear. It becomes softer over time and usually keeps its shape well. However, it can wrinkle easily, and some untreated hemp fabrics may initially feel rough or stiff against sensitive skin.", "image": "assets/library/detail-05.webp", "occasion": "vacation", "page": 7}, {"id": "modal", "name": "Modal", "cn": "莫代尔", "traits": ["Regenerated plant-based fibre", "Soft", "Smooth", "Breathable"], "description": "Modal is a regenerated fibre usually made from beechwood cellulose. It is known for its soft, smooth feel and is commonly used for underwear, T-shirts, pyjamas, sportswear and bedding. It is often blended with cotton or elastane to improve comfort and stretch.", "feel": "Modal usually feels very soft, smooth and cool against the skin. It drapes easily and often has a slightly silky appearance. Compared with ordinary cotton, it may feel lighter, more flexible and less stiff.", "wear": "Modal is suitable for everyday clothing, sleepwear and garments worn close to the skin. Its softness and breathability make it comfortable in warm weather, while its smooth texture is useful for layering under other clothes.", "care": "Check the care label before washing. Use cool or warm water with a gentle machine cycle and mild detergent. Avoid strong bleach and high-temperature drying, as heat may cause shrinking or damage the fibres. Reshape the item while damp and air-dry it when possible. If ironing is needed, use a low-temperature setting.", "notice": "Modal is soft, breathable and good at absorbing moisture. It generally keeps its smooth texture after washing and is less likely to feel stiff than some cotton fabrics. However, thin modal can cling to the body, stretch out of shape or develop small holes if handled roughly.", "image": "assets/library/white-01.webp", "occasion": "everyday", "page": 8}, {"id": "polyester", "name": "Polyester", "cn": "涤纶", "traits": ["Synthetic fibre", "Durable", "Quick-drying", "Wrinkle-resistant"], "description": "Polyester is a synthetic fibre commonly made from petroleum-based materials. It is widely used for sportswear, jackets, dresses, workwear, bags and home textiles. Polyester is also often blended with natural fibres to make fabrics stronger and easier to care for.", "feel": "Polyester can have many different textures. It may feel smooth and silky, soft like cotton or warm like fleece. It usually keeps its shape well and does not wrinkle easily. However, some polyester fabrics may feel less natural or slightly plastic-like.", "wear": "Polyester is suitable for everyday clothing, sportswear, uniforms and travel garments. It dries quickly and keeps its shape, making it useful for exercise, outdoor activities and clothes that need frequent washing. Thicker polyester fabrics are also used for coats and cold-weather clothing.", "care": "Most polyester garments can be machine-washed in cool or warm water. Use a gentle cycle and avoid very high temperatures, as heat may damage or melt the fibres. Air-dry the item or use a low-temperature tumble-dry setting. If ironing is necessary, use low heat. A laundry bag can help reduce friction and the release of microfibres during .", "notice": "Polyester is durable, lightweight and easy to maintain. It resists wrinkles and dries faster than many natural fabrics. However, it may be less breathable, hold body odours and create static electricity. Some polyester garments may also develop small balls of fibre after repeated rubbing.", "image": "assets/library/colour-02.webp", "occasion": "active", "page": 9}, {"id": "nylon", "name": "Nylon", "cn": "尼⻰", "traits": ["Synthetic fibre", "Strong", "Lightweight", "Quick-drying"], "description": "Nylon is a synthetic fibre known for its strength, flexibility and light weight. It is commonly used for sportswear, tights, swimwear, rain jackets, bags, ropes and outdoor equipment. It is often blended with other fibres to improve strength and stretch.", "feel": "Nylon usually feels smooth, light and slightly slippery. It can have a shiny or matte surface depending on how it is made. Thin nylon may feel soft and flexible, while thicker nylon can feel firm and structured.", "wear": "Nylon is suitable for sports, travel and outdoor activities. It dries quickly and is resistant to everyday wear, making it useful for swimwear, windbreakers, tights and lightweight jackets. Stronger nylon fabrics are often used for backpacks and protective clothing.", "care": "Most nylon garments can be machine-washed in cool water using a gentle cycle. Avoid bleach, fabric softener and high-temperature drying. Air-dry the item when possible, as strong heat may shrink, weaken or melt the fibres. If ironing is necessary, use the lowest temperature setting.", "notice": "Nylon is strong, flexible and resistant to abrasion. It is lightweight, easy to pack and dries faster than many natural fabrics. However, it may feel less breathable, create static electricity and hold body odours. It can also be damaged by high temperatures and prolonged sunlight.", "image": "assets/library/white-03.webp", "occasion": "active", "page": 10}, {"id": "denim", "name": "Denim", "cn": "⽜仔布", "traits": ["Woven fabric", "Strong", "Durable", "Structured"], "description": "Denim is a strong twill fabric traditionally made from cotton. Its diagonal weave gives it a durable structure and a distinctive appearance. Denim is commonly used for jeans, jackets, skirts, shirts, bags and workwear. Some modern denim also contains elastane for extra stretch.", "feel": "New denim usually feels firm, thick and slightly stiff. Its surface has visible diagonal lines, and the outer side is often blue while the inside appears lighter. Denim usually becomes softer and develops unique faded areas after repeated wear and washing.", "wear": "Denim is suitable for everyday outfits, casual occasions and practical workwear. Lightweight denim shirts and skirts can be worn in warmer weather, while heavier jeans and jackets are useful in cooler seasons. Dark, clean denim can also work for smart-casual occasions.", "care": "Wash denim only when necessary to help preserve its colour and shape. Turn the garment inside out and machine-wash it in cool water with similar dark colours. Avoid strong bleach and high-temperature drying, as these may cause fading, shrinking or fibre damage. Air-dry the garment when possible.", "notice": "Denim is strong, long-lasting and easy to match with other clothes. Its appearance often becomes more personal with use. However, heavy denim can feel stiff or warm, and dark denim may transfer colour onto light clothing, shoes or furniture. Stretch denim may also lose its shape over time.", "image": "assets/library/wall-04.webp", "occasion": "everyday", "page": 11}, {"id": "canvas", "name": "Canvas", "cn": "帆布", "traits": ["Tightly woven fabric", "Strong", "Firm", "Hard-wearing"], "description": "Canvas is a strong, tightly woven fabric usually made from cotton, hemp or synthetic fibres. Its dense structure makes it more durable than many lightweight fabrics. Canvas is commonly used for bags, shoes, jackets, workwear, tents, furniture and painting surfaces.", "feel": "Canvas usually feels thick, firm and slightly rough. It has a simple woven texture and often holds its shape well. Heavy canvas feels stiff and structured, while lightweight canvas is softer and more flexible. Some canvas fabrics have a waterproof or protective coating.", "wear": "Canvas is suitable for items that need strength and structure, such as tote bags, backpacks, trainers and work jackets. It is also used for outdoor equipment and home furnishings. Lightweight canvas clothing works well for casual outfits, while heavier canvas is better for practical or outdoor use.", "care": "Check the care label because cleaning methods depend on the fibre and any surface coating. Remove light dirt with a soft brush or damp cloth. Wash uncoated canvas in cool water using a gentle cycle, and avoid strong bleach and high heat. Allow it to air-dry completely before storing it to help prevent mould and unpleasant smells.", "notice": "Canvas is durable, resistant to everyday wear and able to carry weight without easily losing its shape. However, thick canvas can feel heavy and stiff. Untreated canvas absorbs water and may take a long time to dry, while coated canvas may be less breathable.", "image": "assets/library/swatch-06.webp", "occasion": "work", "page": 12}, {"id": "rib-knit", "name": "Rib Knit", "cn": "罗纹针织布", "traits": [], "description": "Knitted fabric · Stretchy · Flexible · Close-fitting Rib knit is a knitted fabric made with alternating raised and lowered vertical rows. This structure gives the fabric natural stretch and helps it return to its original shape. It is commonly used for T-shirts, fitted tops, dresses, underwear, collars, cuffs and waistbands.", "feel": "Rib knit has visible vertical lines on its surface. It usually feels soft, flexible and slightly thicker than a basic jersey knit. When stretched, the ribs open and the fabric becomes wider. Its exact feel depends on whether it is made from cotton, wool or synthetic fibres.", "wear": "Rib knit is suitable for comfortable everyday clothing and garments designed to fit close to the body. Lightweight rib knit works well for tops, dresses and underwear. Thicker versions are useful for jumpers, winter layers, collars and cuffs.", "care": "Check the fibre content and care label before washing. Use cool water and a gentle cycle to help protect the fabric’s shape. Avoid pulling or twisting it while wet. Reshape the garment and lay it flat to dry when possible. Fold heavier rib-knit garments instead of hanging them, as hangers may stretch the fabric.", "notice": "Rib knit is stretchy, comfortable and able to follow the shape of the body. It also works well around openings because it can stretch and return to shape. However, thin rib knit may cling to the body or become transparent when stretched. It may also lose its shape if it is hung or pulled for a long time.", "image": "assets/library/pin-08.webp", "occasion": "everyday", "page": 13}, {"id": "satin", "name": "Satin", "cn": "缎⾯", "traits": ["Woven fabric", "Smooth", "Glossy", "Fluid"], "description": "Satin is a type of weave rather than a specific fibre. It can be made from silk, polyester, nylon or other materials. Its special weave creates a smooth, shiny front and a duller back. Satin is commonly used for dresses, blouses, skirts, scarves, sleepwear and bedding.", "feel": "Satin usually feels smooth, cool and slippery. Its glossy surface reflects light, giving it an elegant appearance. The fabric often drapes softly and moves easily, although thicker satin can feel heavier and more structured.", "wear": "Satin is often used for evening wear, weddings, parties and other formal occasions. Satin shirts, skirts and scarves can also be added to everyday outfits. Satin sleepwear and bedding are popular because of their smooth surface.", "care": "Care depends on the fibre used to make the satin, so always check the care label. Some satin items require dry cleaning, while others can be gently hand-washed in cool water. Avoid rubbing, twisting and high temperatures. Air-dry the item away from direct sunlight and iron it from the reverse side using low heat.", "notice": "Satin has a smooth texture, elegant shine and beautiful drape. However, it can show water marks, sweat, creases and small stains easily. The surface may also snag on jewellery, rough nails or sharp objects. Polyester satin may feel less breathable than silk satin.", "image": "assets/library/detail-03.webp", "occasion": "occasion", "page": 14}, {"id": "tulle", "name": "Tulle", "cn": "薄纱", "traits": ["Net fabric", "Lightweight", "Transparent", "Structured"], "description": "Tulle is a fine net fabric usually made from nylon, polyester or sometimes silk. Its open mesh structure makes it lightweight and transparent. It is commonly used for veils, ballet tutus, layered skirts, dresses, costumes and decorative details.", "feel": "Tulle has a fine, visible net pattern and allows light to pass through it. Soft tulle feels light and flexible, while stiff tulle holds its shape and creates volume. Some types may feel slightly rough or scratchy against the skin.", "wear": "Tulle is often used for weddings, parties, dancewear and special occasions. It can add volume to skirts and dresses or be used as a transparent decorative layer. Softer tulle may also appear in modern everyday clothing, usually layered over another fabric.", "care": "Check the care label before cleaning. Hand-wash tulle gently in cool water with a mild detergent. Do not scrub, twist or wring the fabric. Keep it away from high heat because synthetic tulle may melt or lose its shape. Lay it flat or hang it carefully to air-dry. Store it away from sharp objects.", "notice": "Tulle is very light and can create shape and volume without adding much weight. Its transparent surface is useful for layering and decoration. However, it can tear or snag easily on jewellery, zips and rough surfaces. Stiff tulle may also feel uncomfortable when placed directly against the skin.", "image": "assets/library/white-05.webp", "occasion": "occasion", "page": 15}, {"id": "velvet", "name": "Velvet", "cn": "天鹅绒", "traits": ["Pile fabric", "Soft", "Rich texture", "Light-reflecting"], "description": "Velvet is a woven or knitted fabric with a short, dense layer of raised fibres called a pile. It can be made from silk, cotton, viscose, polyester or a blend of fibres. Velvet is commonly used for dresses, jackets, trousers, accessories, curtains and furniture.", "feel": "Velvet usually feels soft, smooth and slightly plush. Its raised surface reflects light differently depending on the direction of the pile, so the colour may appear lighter or darker when viewed from different angles. Some velvet is soft and fluid, while heavier types feel thick and structured.", "wear": "Velvet is often worn in autumn and winter because of its rich and warm appearance. It is popular for evening wear, parties, celebrations and formal events. Velvet jackets, trousers and accessories can also add texture to everyday outfits.", "care": "Always check the care label because different types of velvet require different cleaning methods. Many velvet garments should be dry-cleaned. Avoid rubbing, twisting or pressing the surface with a hot iron. Hang the garment carefully and use gentle steam from a short distance to reduce creases. Store it without placing heavy items on top.", "notice": "Velvet has a distinctive texture, deep colour and elegant appearance. However, its pile can be crushed or flattened by pressure. The surface may also attract dust, show marks and catch on rough objects. Some velvet fabrics are heavy or less breathable, depending on their fibre content.", "image": "assets/library/detail-03.webp", "occasion": "occasion", "page": 16}, {"id": "corduroy", "name": "Corduroy", "cn": "灯芯绒", "traits": ["Pile fabric", "Ribbed", "Durable", "Warm"], "description": "Corduroy is a strong fabric with raised vertical ridges called wales. It is usually made from cotton, but it may also contain polyester or elastane. Corduroy is commonly used for trousers, jackets, shirts, skirts, hats and children’s clothing.", "feel": "Corduroy feels soft and slightly plush, with clear parallel lines running along its surface. Fine-wale corduroy has narrow ridges and usually feels lighter, while wide-wale corduroy has thicker ridges and a heavier, more textured appearance.", "wear": "Corduroy is especially suitable for autumn and winter because it feels warmer and thicker than many lightweight fabrics. It works well for casual trousers, overshirts and jackets. Fine corduroy can also be used for smart-casual outfits, while heavier types are suitable for practical everyday clothing.", "care": "Check the care label before washing. Turn corduroy garments inside out and wash them in cool water on a gentle cycle. Avoid washing them with lint-producing items such as towels. Do not use high-temperature drying, as heat may cause shrinking or flatten the pile. Air-dry the garment and gently brush the surface in the direction of the ridges if needed.", "notice": "Corduroy is durable, warm and comfortable. Its raised texture gives clothing a distinctive appearance and helps hide small creases. However, the pile can become flattened in areas that experience frequent rubbing. The fabric may also attract dust and show pressure marks.", "image": "assets/library/pin-08.webp", "occasion": "winter", "page": 17}, {"id": "tweed", "name": "Tweed", "cn": "粗花呢", "traits": ["Woven fabric", "Textured", "Warm", "Durable"], "description": "Tweed is a thick, textured fabric traditionally made from wool. It is woven using different coloured yarns, which can create small checks, herringbone patterns or mixed-colour surfaces. Tweed is commonly used for jackets, coats, suits, skirts, hats and bags.", "feel": "Tweed usually feels firm, thick and slightly rough. Its surface has a visible woven texture and may contain small flecks of different colours. Traditional wool tweed can feel coarse, while modern blends may be softer, lighter and more flexible.", "wear": "Tweed is especially suitable for autumn and winter because it provides warmth and structure. Tweed jackets, coats and skirts work well for work, smart-casual outfits and formal occasions. Lighter tweed can also be used during cooler spring weather.", "care": "Always check the care label. Many wool tweed garments require dry cleaning. Remove light dirt with a soft clothes brush and allow the garment to air between wears. Avoid frequent washing, strong rubbing and high heat. Store tweed folded or on a supportive hanger, and protect wool tweed from moths.", "notice": "Tweed is warm, durable and good at keeping its shape. Its textured surface can hide small creases and signs of wear. However, some tweed may feel itchy against bare skin, so garments are often lined. The fabric can also feel heavy, and its loose surface yarns may catch on sharp objects.", "image": "assets/library/swatch-05.webp", "occasion": "work", "page": 18}, {"id": "fleece", "name": "Fleece", "cn": "摇粒绒", "traits": ["Synthetic fabric", "Soft", "Warm", "Lightweight"], "description": "Fleece is a soft, knitted fabric with a raised, fluffy surface. It is usually made from polyester and is designed to trap warm air close to the body. Fleece is commonly used for jackets, hoodies, blankets, outdoor clothing and warm inner layers.", "feel": "Fleece usually feels soft, fluffy and warm. It is lighter than many wool fabrics and may have a brushed surface on one or both sides. Thin fleece feels flexible and works well for layering, while thick fleece provides more warmth and volume.", "wear": "Fleece is suitable for cool weather, outdoor activities, travelling and relaxed everyday wear. It can be worn as a middle layer under a waterproof jacket or as an outer layer in dry, mild weather. It is also useful for comfortable clothing worn at home.", "care": "Wash fleece in cool water on a gentle cycle and turn the garment inside out. Avoid fabric softener, bleach and high-temperature drying, as these may damage the fibres and reduce performance. Air-dry it when possible. Washing it less often and using a microfibre-catching laundry bag or filter can help reduce the release of synthetic fibres.", "notice": "Fleece is lightweight, warm and quick-drying. It is usually easy to wash and can provide warmth even when slightly damp. However, it may be less breathable than natural fibres, create static electricity and develop small balls of fibre after repeated rubbing. Most fleece is not windproof or waterproof unless it has an additional protective layer.", "image": "assets/library/white-07.webp", "occasion": "active", "page": 19}];